    lambda tokens, pairs_before, kwarg_names_for_insert: all(
        sum(1 for t in tokens if (t.name, t.src) == pair)
        == sum(1 for p in pairs_before if p == pair)
        + (1 if pair[0] == "CODE" and pair[1] in tuple(f"{kw}=" for kw in kwarg_names_for_insert) else 0)
        for pair in set(pairs_before) | set((t.name, t.src) for t in tokens)
    )
)
